\section{Preliminaries}\label{sec:prelims}
We define a database $D \in \cX^n$ to be an ordered tuple of $n$ rows $(x_1,\ldots,x_n) \in \cX$, where $\cX$ is the data universe. For our purposes, we typically take $\cX = \{0,1\}^d$.

\begin{definition}[Accuracy]
    Randomized algorithm $\cA: \cX^n \to \bbR^{d}$ is $(\alpha,p)$-accurate for problem $\cP$ if for every $D \in \cX^n$, with probability at least $1-p$, the output of $\cA$ is a vector $a \in \{0,1\}^d$ that satisfies $\vert a_\cP(D) - a \vert \leq \alpha$ where $a_\cP(D)$ denotes the exact solution of the problem $\cP$ on input $D$.
\end{definition}

The following definition of fingerprinting codes is ``fully-collusion-resilient''. For any coalition of users $S$ who collectively produce a string $y \in \{0,1\}^d$ as output, as long as $y$ satisfies the \textit{marking condition} -- for all positions $1 \leq j \leq d$, if the values $x_{ij}$ for all users $i$ in coalition $S$ agree with some letter $s \in \{0,1\}$, then $y_j =s$ -- then the combined codeword $y$ can be traced back to a user in the coalition.  Formally, for a codebook $C \in \{0,1\}^{n \times d}$, and a coalition $S \subseteq [n]$, we define the set of feasible codewords for $C_S$ to be
\[F(C_S) = \{c' \in \{0,1\}^d \mid \forall j \in [d],\exists i \in S, c'_j = c_{ij}\}\]
\begin{definition}[Fingerprinting Codes~\cite{BunUV18}]\label{def:fpc}
    For any $n,d \in \bbN, \xi \in (0,1]$, a pair of algorithms $(Gen,Trace)$ is an $(n,d,c)$-fingerprinting code with security $\xi$ against a coalition of size $c$ if $Gen$ outputs a codebook $C \in \{0,1\}^{n\times d}$ and secret state $st$ and for every (possibly randomized) adversary $\cA_{FP}$, and every coalition $S \subseteq [n]$ such that $\vert S \vert \leq c$, if we set $c' \leftarrow_R \cA_{FP}(C_S)$ then 
    \begin{enumerate}
        \item $\Pr[c' \in F(C_S) \wedge Trace(c') = \perp ]\leq \xi $
        \item $\Pr[Trace(c') \in [n]\setminus S]\leq \xi$
    \end{enumerate}
    where $C_S$ contains the rows of $C$ given by $S$, and the probability is taken over the coins of $C$, $Trace$, and $\cA_{FP}$. The algorithms $Gen$ and $Trace$ may share a common state denoted as $st$.
\end{definition}

\section{Permute Rows and Pad and Permute Columns Fingerprinting Codes (PR-PPC FPC)}\label{sec:prppc}
In this section, we first introduce our pad and permute variant of the original fingerprinting codes where we Permute Rows and Pad and Permute Columns (PR-PPC $(n,d,c,\ell)$-FPC). Given $(Gen, Trace)$ of an $(n,d,c)$-FPC, we construct $Gen'$ and $Trace'$ in \cref{alg:gen'} and \cref{alg:trace'} to produce a PR-PPC $(n,d,c,\ell)$-FPC. In more detail, $Gen'$ samples codebook $C$ and secret state $st$ from $Gen$ where $C\in \{0,1\}^{n\times d}$. It then permutes the rows via a random permutation $\pi_R$, after which it pads $2\ell$ columns and performs another random permutation $\pi$ on the columns. Then, it releases the resulting codebook $C' \in \{0,1\}^{n\times d'}$, where $d'=d+2\ell$ and $\ell$ is the parameter which controls the number of columns padded to $C$. Note that the row permutation $\pi_R$ is public while the column permutation $\pi$ is part of the new secret state $st'$. The algorithm $Trace'$ receives an answer vector of dimension $d'$ and uses its secret state $st'=(st,\pi)$ to feed the vector entries that correspond to the original first $d$ columns via $\pi^{-1}$ to $Trace$ and releases the output of $Trace$. 

\begin{algorithm}[!htb]
\caption{$Gen'$}
\label{alg:gen'}
\begin{algorithmic}[1]
\Require{Number of users $n \in \bbN$, number of padded 0/1 columns $\ell$}
\State Sample codebook $(C,st) \leftarrow Gen(n)$ such that $C \in \{0,1\}^{n \times d}$. 
\State Sample random permutation $\pi:[d'] \to [d']$ where $d':= d+2 \ell$. For an $n \times d'$ matrix $A$, define $n\times d'$ matrix $\pi(A)$ such that $\pi(j)$-th column of $\pi(A)$ equals to the $j$-th column of $A$ for every $j \in [d']$.
\State Sample random permutation $\pi_R : [n] \to [n]$. For an $n$-row matrix $A$, define $\pi_R(A)$ such that $\pi_R(i)$-th row of $\pi_R(A)$ equals to the $i$-th row of $A$ for every $i \in [n]$. 
\State $C^{\pi_R} \leftarrow $ Permute rows of $C$ via random permutation $\pi_R$.
\State $C_{pad}\leftarrow $ Pad $\ell$ columns of all 1's and $\ell$ columns of all 0's to matrix $C^{\pi_R}$.
\State $C' \leftarrow $Permute the columns of $C_{pad}$ according to random permutation $\pi$. \State Output $C'$ along with the new secret state $st':=(st, \pi)$ and permutation $\pi_R$.
\end{algorithmic}
\end{algorithm}

\begin{algorithm}[!htb]
\caption{$Trace'$}
\label{alg:trace'}
\begin{algorithmic}[1]
\Require{Answer vector $\mathbf{a} =(a^1, \ldots, a^{d'}) \in \{0,1\}^{d'}$, secret state $st'=(\pi,st)$ }
\State Output $Trace(\mathbf{a}_{og},st)$ where $\mathbf{a}_{og}=(a^{\pi(1)}, \ldots, a^{\pi(d)}) \in \{0,1\}^{d}$.
\end{algorithmic}
\end{algorithm}

We define the \emph{feasible sample property} of an FPC below. 

\begin{definition}[Feasible Sample Property]\label{def:feasible-sample}
    Let $C \in \{0,1\}^{n\times d}$ be a codebook of an $(n,d,c)$-FPC, $S \subseteq [n]$ be a coalition and $C_S \subseteq C$ be the matrix consisting of the corresponding rows indexed by $S$. Given an algorithm $\cA$ that takes as input $C_S$ and outputs a vector $\mathbf{o} \in \{0,1\}^d$, the feasible sample property states that if $\mathbf{o} \in F(C)$, then $\mathbf{o} \in F(C_S)$. 
\end{definition}

\section{Lower Bound}\label{sec:lowerbound}
\subsection{Warm Up: Using a Random Oracle}\label{sec:ro}
\begin{definition}[Random Oracle Problem $\cP_{RO}$]\label{def:ro}
Given a random oracle $H: [n] \to \{0,1\}^d$, and a dataset $D=(x_1, \ldots, x_n)$ where $x_i \in \{0,1\}^d$,
define dataset $D_{H}:=(z_1, \ldots, z_n)$ where $z_i=H(i)\oplus x_i$. For simplicity of notation, we refer to the operation for obtaining $D_H$ from $D$ as $H(D)$. The problem $\cP_{RO}$ on input $D_H$ releases the one-way marginals of $D$.

We use $\cP_{RO}(D)$ to denote that $\cP_{RO}$ releases the one-way marginals of the underlying dataset $D$. 
\end{definition}

 Let $(Gen, Trace)$ be the promised $(n,d,c)$-fingerprinting code in the theorem statement. We first construct a PR-PPC $(n,d,c,\ell)$-FPC with $\ell:=100d$ (see \cref{sec:prppc} for details). 

 The distribution $\cC_\cS$ on $c$-row databases is implicitly defined through the sampling process below
 \begin{enumerate}
 \item Let $C' \leftarrow Gen'(n,100d)$ (see \cref{alg:gen'}) where $C' \in \{0,1\}^{n \times d'}$ and $d'=d+100d=101d$. Note that $Gen'$ also outputs $\pi_R$ which is a public permutation on rows. 
     \item Let $C'_S =(x_1, \ldots, x_c)\in \{0,1\}^{c \times d'}$ be the first $c$ rows of $C' \in \{0,1\}^{n\times d'}$
     \item Output $C'_S$
 \end{enumerate}

    \noindent{\bfseries {Adversary $\cB$ Algorithm. }}
    Adversary $\cB$ receives $C'_S$ as input and does the following: 
    \begin{enumerate}
        \item Create a database $D =(r_1,\ldots, r_n) \in \{0,1\}^{n \times d'}$ where each row $r_i \in \{0,1\}^{d'}$ consists of 0/1 entries sampled independently and uniformly at random.\item Given oracle access to randomized algorithm $\cA$ which solves $\cP_{RO}$ on input $D$, $\cB$ simulates the answer to the distinct $i_j$-th row query (where $j\in [c]$) made by $\cA$ to random oracle $H$ as follows: 
        \begin{enumerate}
            \item  Return $H(i_j):= r_{i_j} \oplus x_j$. \end{enumerate}
        \item Let $\mathbf{a}$ be the output of $\cA(D)$ where $\mathbf{a} \in [0,1]^{d'}$. Round each entry of $\mathbf{a}$ to $\{0,1\}$, call this new vector $\mathbf{\bar{a}} \in \{0,1\}^{d'}$. \item Output $Trace'(\mathbf{\bar{a}})$
    \end{enumerate}

    Recall the notation in \cref{def:ro} where $\cP_{RO}(C')$ means that $\cP_{RO}$ releases the one-way marginals of the underlying dataset $C'$.
